"use client";

import { useEffect, useLayoutEffect, useState } from "react";

// Shared by the motion components. They are optional extras: a project that never
// adds one never carries this file's callers. Every effect follows the same rules:
//   - it is decoration, so the animated layers are hidden from assistive technology
//   - it stands still for people who ask for less motion
//   - it can be paused (isPaused), because moving content must be stoppable
//   - its keyframes and still rules live in one CSS file (motion/rdloom-motion.css) that
//     `rdloom add` installs and imports from your tokens file, so there is nothing to set up

/** useLayoutEffect in the browser, useEffect on the server (which would otherwise warn). */
export const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** Does the visitor ask for less motion? Reads the setting at call time, so it is safe to use in a layout effect. */
export const prefersReducedMotion = () =>
  typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/** True when the visitor asks for less motion, and updates if they change the setting. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return reduced;
}

/** The inline style for the optional CSS variables an effect reads: only the ones that were given. */
export function motionVars(vars: Record<string, string | number | undefined>): React.CSSProperties {
  return Object.fromEntries(Object.entries(vars).filter(([, v]) => v !== undefined)) as React.CSSProperties;
}

// How a block learns what the person may do. Your app decides (from roles, plans, record state, anything);
// the block only receives the answer for each action. This is for what people see and can try: the server
// must check every action again, because anything in the browser can be changed.

/** What a block does with an action: show it normally, show it but not allow it, or leave it out. */
export type PermissionState = "allow" | "disabled" | "hidden";

/**
 * An answer for one action. true and false are the short forms (false means disabled). Use an object to say
 * why, so the person is told: { state: "disabled", reason: "Only admins can delete" }.
 */
export type PermissionValue = boolean | PermissionState | { state: PermissionState; reason?: string };

/** The answers for a block's actions, by action name. An action you leave out is allowed. */
export type Permissions<Action extends string = string> = Partial<Record<Action, PermissionValue>>;

export interface ResolvedPermission {
  state: PermissionState;
  /** Why the action is disabled or hidden, when the app said. */
  reason?: string;
  /** Show the control at all. */
  isVisible: boolean;
  /** Show it but do not allow it. */
  isDisabled: boolean;
  /** Run it. */
  isAllowed: boolean;
}

function resolved(state: PermissionState, reason?: string): ResolvedPermission {
  return { state, reason, isVisible: state !== "hidden", isDisabled: state === "disabled", isAllowed: state === "allow" };
}

/** Turns any form of answer into one shape. A missing answer means allowed. */
export function resolvePermission(value: PermissionValue | undefined): ResolvedPermission {
  if (value === undefined || value === true) return resolved("allow");
  if (value === false) return resolved("disabled");
  if (typeof value === "string") return resolved(value);
  return resolved(value.state, value.reason);
}

/** The answer for one action in a block's permissions. */
export function permissionFor<Action extends string>(permissions: Permissions<Action> | undefined, action: Action): ResolvedPermission {
  return resolvePermission(permissions?.[action]);
}

/** True when the action may run. */
export const can = <Action extends string>(permissions: Permissions<Action> | undefined, action: Action) => permissionFor(permissions, action).isAllowed;

/** Builds a Permissions object from yes/no answers, e.g. from a function you already have. */
export function permissionsFrom<Action extends string>(actions: readonly Action[], check: (action: Action) => boolean, reason?: (action: Action) => string | undefined): Permissions<Action> {
  const result: Permissions<Action> = {};
  for (const action of actions) result[action] = check(action) ? true : { state: "disabled", reason: reason?.(action) };
  return result;
}

"use client";

import { useEffect, useState, type RefObject } from "react";

/**
 * Tells you which edges of a sideways-scrolling box still have hidden content, so a fade can say "this scrolls".
 * Put the result on the box as `data-hint` and add `scrollHintClass`.
 */
export function useScrollHint(ref: RefObject<HTMLElement | null>): "left" | "right" | "both" | undefined {
  const [hint, setHint] = useState<"left" | "right" | "both" | undefined>();
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const rtl = getComputedStyle(el).direction === "rtl";
    const update = () => {
      const max = el.scrollWidth - el.clientWidth;
      if (max <= 1) return setHint(undefined);
      const pos = Math.abs(el.scrollLeft);
      const before = pos > 1;
      const after = pos < max - 1;
      const left = rtl ? after : before;
      const right = rtl ? before : after;
      setHint(left && right ? "both" : right ? "right" : left ? "left" : undefined);
    };
    update();
    el.addEventListener("scroll", update, { passive: true });
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(update);
    observer?.observe(el);
    if (el.firstElementChild) observer?.observe(el.firstElementChild);
    return () => {
      el.removeEventListener("scroll", update);
      observer?.disconnect();
    };
  }, [ref]);
  return hint;
}

/** The fade at the edge that still has content. The sides are physical (left and right). */
export const scrollHintClass =
  "data-[hint=right]:[mask-image:linear-gradient(to_right,#000_calc(100%-2rem),transparent)] " +
  "data-[hint=left]:[mask-image:linear-gradient(to_left,#000_calc(100%-2rem),transparent)] " +
  "data-[hint=both]:[mask-image:linear-gradient(to_right,transparent,#000_2rem,#000_calc(100%-2rem),transparent)]";

/** The same for a box that scrolls up and down: which edge still has hidden content. Use `data-vhint` and `scrollHintYClass`. */
export function useVerticalScrollHint(ref: RefObject<HTMLElement | null>, watch?: unknown): "top" | "bottom" | "both" | undefined {
  const [hint, setHint] = useState<"top" | "bottom" | "both" | undefined>();
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const update = () => {
      const max = el.scrollHeight - el.clientHeight;
      if (max <= 1) return setHint(undefined);
      const before = el.scrollTop > 1;
      const after = el.scrollTop < max - 1;
      setHint(before && after ? "both" : after ? "bottom" : before ? "top" : undefined);
    };
    update();
    el.addEventListener("scroll", update, { passive: true });
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(update);
    observer?.observe(el);
    if (el.firstElementChild) observer?.observe(el.firstElementChild);
    return () => {
      el.removeEventListener("scroll", update);
      observer?.disconnect();
    };
  }, [ref, watch]);
  return hint;
}

export const scrollHintYClass =
  "data-[vhint=bottom]:[mask-image:linear-gradient(to_bottom,#000_calc(100%-1.5rem),transparent)] " +
  "data-[vhint=top]:[mask-image:linear-gradient(to_top,#000_calc(100%-1.5rem),transparent)] " +
  "data-[vhint=both]:[mask-image:linear-gradient(to_bottom,transparent,#000_1.5rem,#000_calc(100%-1.5rem),transparent)]";

"use client";

import type { ReactNode } from "react";
import type { DataState } from "./state";

export interface StateBoundaryProps {
  state: DataState;
  /** Shown while the data loads. A skeleton or a spinner. */
  loading?: ReactNode;
  /** Shown when there is nothing to list yet. */
  empty?: ReactNode;
  /** Shown when loading failed. Say what happened and offer a retry. */
  error?: ReactNode;
  /** The data itself. */
  children?: ReactNode;
}

/** Renders the slot that matches a DataState. It does not fetch anything. */
export function StateBoundary({ state, loading = null, empty = null, error = null, children }: StateBoundaryProps) {
  switch (state) {
    case "loading":
      return <div aria-busy="true">{loading}</div>;
    case "empty":
      return <>{empty}</>;
    case "error":
      return <>{error}</>;
    default:
      return <>{children}</>;
  }
}

// The two kinds of state every screen has, kept as two separate types.
// DataState describes the data a screen shows; ActionState describes something
// the person did (a submit, a delete). Both map onto flags apps already have
// from their own data layer. Nothing here fetches or caches anything.

/** What a screen has to show: wait for it, nothing to show, it failed, or it is here. */
export type DataState = "loading" | "empty" | "error" | "ready";

/** What happened to an action: not started, running, worked, or failed. */
export type ActionState = "idle" | "pending" | "success" | "error";

/** Maps the flags most data libraries return to a DataState. Errors win, then loading, then empty. */
export function toDataState({
  isLoading,
  error,
  isEmpty,
}: {
  isLoading?: boolean;
  error?: unknown;
  isEmpty?: boolean;
}): DataState {
  if (error) return "error";
  if (isLoading) return "loading";
  return isEmpty ? "empty" : "ready";
}

/** Maps the flags most mutation helpers return to an ActionState. */
export function toActionState({
  isPending,
  error,
  isSuccess,
}: {
  isPending?: boolean;
  error?: unknown;
  isSuccess?: boolean;
}): ActionState {
  if (isPending) return "pending";
  if (error) return "error";
  return isSuccess ? "success" : "idle";
}

"use client";

// Keep a screen's state in the address bar (search text, filters, sort, page, tab), so a refresh,
// a shared link and the back button all bring the same screen back.
//
// You describe the state once as a schema: for each key, its type, its default and (optionally)
// the name to use in the address. parseQueryState reads an address query into a typed object and
// serializeQueryState writes it back. Anything missing or invalid becomes the default; nothing
// here throws. Lists are written as repeated keys (?tag=a&tag=b).
//
// useQueryState works with any router: your app says how to read the current query and how to
// write a new one (Next.js, Remix, React Router or plain history). useWindowQueryState is the
// plain-browser version using window.location and history. Nothing touches window unless you use
// that hook, and it is safe to render on the server. Writing keeps every other parameter in the
// address as it was. Nothing is debounced: debounce typing in your own code if you need it.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

export type QueryField =
  | { type: "string"; default: string; name?: string }
  | { type: "number"; default: number; name?: string; min?: number; max?: number; integer?: boolean }
  | { type: "boolean"; default: boolean; name?: string }
  | { type: "enum"; values: readonly string[]; default: string; name?: string }
  | { type: "array"; default: readonly string[]; name?: string };

export type QuerySchema = Record<string, QueryField>;

type FieldValue<F extends QueryField> = F extends { type: "string" }
  ? string
  : F extends { type: "number" }
    ? number
    : F extends { type: "boolean" }
      ? boolean
      : F extends { type: "enum"; values: readonly (infer V)[] }
        ? V
        : F extends { type: "array" }
          ? string[]
          : never;

/** The typed state a schema describes. Use `as const` on enum values to get a union type. */
export type QueryState<S extends QuerySchema> = { [K in keyof S]: FieldValue<S[K]> };

const urlName = (key: string, field: QueryField) => field.name ?? key;

function toParams(search: string | URLSearchParams): URLSearchParams {
  if (typeof search !== "string") return new URLSearchParams(search);
  return new URLSearchParams(search.startsWith("?") ? search.slice(1) : search);
}

function clamp(n: number, field: Extract<QueryField, { type: "number" }>): number {
  let value = field.integer === false ? n : Math.trunc(n);
  if (field.min != null && value < field.min) value = field.min;
  if (field.max != null && value > field.max) value = field.max;
  return value;
}

function readField(params: URLSearchParams, key: string, field: QueryField): unknown {
  const name = urlName(key, field);
  const raw = params.getAll(name);
  switch (field.type) {
    case "string":
      return raw.length ? raw[0] : field.default;
    case "number": {
      if (!raw.length || raw[0].trim() === "") return clamp(field.default, field);
      const n = Number(raw[0]);
      return Number.isFinite(n) ? clamp(n, field) : clamp(field.default, field);
    }
    case "boolean": {
      const v = raw[0];
      if (v === "true" || v === "1") return true;
      if (v === "false" || v === "0") return false;
      return field.default;
    }
    case "enum":
      return raw.length && field.values.includes(raw[0]) ? raw[0] : field.default;
    case "array":
      return raw.length ? raw : [...field.default];
  }
}

function sameValue(a: unknown, b: unknown): boolean {
  if (Array.isArray(a) && Array.isArray(b)) return a.length === b.length && a.every((v, i) => v === b[i]);
  return a === b;
}

/** Reads an address query ("?page=2&tag=a" or "page=2") into typed state. Missing or invalid values become the default. */
export function parseQueryState<S extends QuerySchema>(search: string | URLSearchParams, schema: S): QueryState<S> {
  const params = toParams(search);
  const state: Record<string, unknown> = {};
  for (const key of Object.keys(schema)) state[key] = readField(params, key, schema[key]);
  return state as QueryState<S>;
}

export interface SerializeOptions {
  /** Leave out values equal to their default, for a shorter address. Default true. */
  omitDefaults?: boolean;
  /** An existing query whose other parameters are kept. Parameters named in the schema are replaced. */
  base?: string | URLSearchParams;
}

/** Writes state to a query string (without the leading "?"). Other parameters in `base` are kept. */
export function serializeQueryState<S extends QuerySchema>(
  state: Partial<QueryState<S>>,
  schema: S,
  { omitDefaults = true, base }: SerializeOptions = {},
): string {
  const params = base === undefined ? new URLSearchParams() : toParams(base);
  for (const key of Object.keys(schema)) {
    const field = schema[key];
    const name = urlName(key, field);
    params.delete(name);
    const value = key in state ? (state as Record<string, unknown>)[key] : field.default;
    // Run the value through the reader so an out-of-range or wrong-typed value is cleaned the same way.
    const clean = readField(toParams(writeOne(name, field, value)), key, field);
    if (omitDefaults && sameValue(clean, readField(new URLSearchParams(), key, field))) continue;
    for (const [k, v] of toParams(writeOne(name, field, clean))) params.append(k, v);
  }
  return params.toString();
}

function writeOne(name: string, field: QueryField, value: unknown): string {
  const out = new URLSearchParams();
  if (field.type === "array") {
    const list = Array.isArray(value) ? value : [];
    for (const item of list) out.append(name, String(item));
  } else if (value !== undefined && value !== null) {
    out.set(name, String(value));
  }
  return out.toString();
}

export interface UseQueryStateOptions {
  /** The current query string, read from your router (for example useSearchParams().toString()). */
  search: string;
  /** Called with the new full query string (no "?"). Write it to the address with your router. */
  onChange: (search: string) => void;
  /** Leave out values equal to their default. Default true. */
  omitDefaults?: boolean;
}

export type QueryStateUpdate<S extends QuerySchema> = Partial<QueryState<S>> | ((current: QueryState<S>) => Partial<QueryState<S>>);

/**
 * State kept in the address. The app supplies how to read and write the query, so it works with any router.
 * Returns [state, setState]; setState merges the changes you pass and keeps unrelated parameters.
 */
export function useQueryState<S extends QuerySchema>(
  schema: S,
  { search, onChange, omitDefaults = true }: UseQueryStateOptions,
): [QueryState<S>, (update: QueryStateUpdate<S>) => void] {
  const state = useMemo(() => parseQueryState(search, schema), [search, schema]);
  const latest = useRef({ search, state, onChange, schema, omitDefaults });
  latest.current = { search, state, onChange, schema, omitDefaults };

  const setState = useCallback((update: QueryStateUpdate<S>) => {
    const { state: current, search: currentSearch, schema: sch, onChange: change, omitDefaults: omit } = latest.current;
    const patch = typeof update === "function" ? update(current) : update;
    const next = { ...current, ...patch } as QueryState<S>;
    const query = serializeQueryState(next, sch, { omitDefaults: omit, base: currentSearch });
    // Keep what the next call reads in step, so two updates in the same tick build on each other.
    latest.current.search = query;
    latest.current.state = parseQueryState(query, sch);
    change(query);
  }, []);

  return [state, setState];
}

export interface UseWindowQueryStateOptions {
  /** "push" adds a history entry (back button steps through changes); "replace" overwrites the current one. Default "push". */
  mode?: "push" | "replace";
  omitDefaults?: boolean;
}

/** The query string of the current address, or "" on the server. */
function windowSearch(): string {
  return typeof window === "undefined" ? "" : window.location.search.replace(/^\?/, "");
}

/**
 * useQueryState on the plain browser address. Renders with the default state on the server and
 * first client render, reads the real address after mount, and follows the back and forward buttons.
 */
export function useWindowQueryState<S extends QuerySchema>(
  schema: S,
  { mode = "push", omitDefaults = true }: UseWindowQueryStateOptions = {},
): [QueryState<S>, (update: QueryStateUpdate<S>) => void] {
  const [search, setSearch] = useState("");
  useEffect(() => {
    setSearch(windowSearch());
    const onPop = () => setSearch(windowSearch());
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const onChange = useCallback(
    (next: string) => {
      const url = `${window.location.pathname}${next ? `?${next}` : ""}${window.location.hash}`;
      if (mode === "replace") window.history.replaceState(window.history.state, "", url);
      else window.history.pushState(window.history.state, "", url);
      setSearch(next);
    },
    [mode],
  );

  return useQueryState(schema, { search, onChange, omitDefaults });
}

"use client";

import { useLocale } from "react-aria-components";

/**
 * The locale a component formats numbers and dates with. An explicit locale wins. Otherwise it is
 * React Aria's locale: en-US while rendering on the server and during hydration, the browser's
 * language after that. Never call Intl or toLocale*String with an undefined locale in a component:
 * the server and the first client render would disagree and React would report a hydration error.
 */
export function useDefaultLocale(explicit?: string): string {
  const { locale } = useLocale();
  return explicit || locale;
}

/** Narrow no-break and thin spaces differ between Node and browsers; one normal space reads the same everywhere. */
export function plainSpaces(text: string): string {
  return text.replace(/[   ]/g, " ");
}

"use client";

import { useSyncExternalStore } from "react";

/**
 * True while `query` matches. On the server (and during hydration) it
 * returns `serverValue`, so pick the value your mobile-first layout expects.
 */
export function useMediaQuery(query: string, serverValue = false): boolean {
  return useSyncExternalStore(
    (onChange) => {
      const list = window.matchMedia(query);
      list.addEventListener("change", onChange);
      return () => list.removeEventListener("change", onChange);
    },
    () => window.matchMedia(query).matches,
    () => serverValue,
  );
}
